#!/usr/bin/env bash
set -Eeuo pipefail
DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")"&&pwd -P);source "$DIR/lib/device-health-common.sh";[[ $# -eq 2&&$1 == --confirm-module-disabled&&( $2 == --restore-latest||$2 == --remove-current ) ]]||dh_fail 'usage: rollback-device-health.sh --confirm-module-disabled (--restore-latest|--remove-current)';dh_root;dh_environment;TARGET="$DH_MODULES/DeviceHealth";[[ -d $TARGET ]]||dh_fail 'installed module missing';STAMP=$(date -u +%Y%m%d-%H%M%S);if [[ $2 == --restore-latest ]];then NAME=$(find "$DH_MODULES" -mindepth 1 -maxdepth 1 -type d -name 'DeviceHealth.backup-*' -printf '%f\n'|sort|tail -n1);[[ -n $NAME ]]||dh_fail 'no backup';mv "$TARGET" "$DH_MODULES/DeviceHealth.rollback-replaced-$STAMP";mv "$DH_MODULES/$NAME" "$TARGET";else mv "$TARGET" "$DH_MODULES/DeviceHealth.removed-$STAMP";fi;dh_info "RUNTIME_CONFIGURATION=PRESERVED:${DEVICE_HEALTH_RUNTIME_DIR:-/var/lib/zabbix/device-health}";dh_info PASS
